func TestAgreementNativeListAddressSource(t *testing.T) {
	t.Parallel()
	for _, tc := range agreementNativeListAddressControls() {
		t.Run(tc.Name, func(t *testing.T) {
			t.Parallel()
			s := agreementNativeListAddressReading(tc.Body)
			if diff := cmp.Diff(tc.Source, s); diff != "" {
				t.Fatalf("caught: complete tight-list address source (-want +got):\n%s", diff)
			}
			if diff := cmp.Diff(tc.Owners, agreementNativeListAddressOwners(&s.Address.Original, &s.Original, s.Lists)); diff != "" {
				t.Fatalf("caught: complete tight-list address owner roster (-want +got):\n%s", diff)
			}
		})
	}
}
func TestAgreementNativeListAddressPublic(t *testing.T) {
	t.Parallel()
	for _, tc := range agreementNativeListAddressControls() {
		t.Run(tc.Name, func(t *testing.T) {
			t.Parallel()
			c := agreementCase{Body: tc.Body}
			_, a := agreementIsolatedPage(t, c)
			fs := agreementFragmentFailures(t, []agreementCase{c}, []agreementHTML{a})[0]
			p := agreementNativeListAddressBudget(t, c.Body, &a, fs)
			if diff := cmp.Diff(tc.Blocks, a.Blocks); diff != "" {
				t.Fatalf("caught: complete tight-list address original page set (-want +got):\n%s", diff)
			}
			if diff := cmp.Diff(tc.Payload, p); diff != "" {
				t.Fatalf("caught: complete tight-list address public budget (-want +got):\n%s", diff)
			}
			if tc.Source.Address.Valid {
				agreementNativeListAddressLedgers(t, &tc, c, &a)
			}
			owned := make(map[string]int)
			for _, f := range fs {
				if k, authority, wrong := agreementNativeListAddressDifference(c, &f, &a, fs, &p); k != "" {
					owned[agreementSignature(&f)+" / "+k+" / "+authority+" / "+wrong]++
					agreementNativeListAddressDrift(t, c, &f, &a, fs, &p)
				}
			}
			if diff := cmp.Diff(tc.Owned, owned); diff != "" {
				t.Fatalf("caught: complete tight-list address public ownership (-want +got):\n%s", diff)
			}
		})
	}
}
func agreementNativeListAddressLedgers(t *testing.T, tc *agreementNativeListAddressControl, c agreementCase, a *agreementHTML) {
	t.Helper()
	_, w := agreementIsolatedPage(t, agreementCase{Body: tc.Source.Address.Body})
	if diff := cmp.Diff(tc.WitnessBlocks, w.Blocks); diff != "" {
		t.Fatalf("caught: complete tight-list address private page set (-want +got):\n%s", diff)
	}
	names := agreementNativeAddressNames(&tc.Source.Address, a, &w)
	if diff := cmp.Diff(tc.Names, names); diff != "" {
		t.Fatalf("caught: complete tight-list address public namespace (-want +got):\n%s", diff)
	}
	before, after := agreementNativeAddressPublic(t, c.Body, a, names), agreementNativeAddressPublic(t, tc.Source.Address.Body, &w, names)
	if diff := cmp.Diff(tc.Original, before); diff != "" {
		t.Fatalf("caught: complete tight-list address original ledger (-want +got):\n%s", diff)
	}
	if diff := cmp.Diff(tc.Witness, after); diff != "" {
		t.Fatalf("caught: complete tight-list address projected ledger (-want +got):\n%s", diff)
	}
}
func agreementNativeListAddressDrift(t *testing.T, c agreementCase, f *agreementFailure, a *agreementHTML, fs []agreementFailure, p *agreementNativeListAddressPayload) {
	t.Helper()
	for _, other := range []agreementCase{{Body: c.Body + "unowned"}, {Body: c.Body, Title: "title"}, {Body: c.Body, Companions: capturedBodies{"A.md": "words"}}} {
		if k, _, _ := agreementNativeListAddressDifference(other, f, a, fs, p); k != "" {
			t.Fatal("caught: tight-list address borrowed source or vault context")
		}
	}
	for _, change := range []func(*agreementFailure){func(f *agreementFailure) { f.Property = "unowned" }, func(f *agreementFailure) { f.Identity = "unowned" }, func(f *agreementFailure) { f.Tuple.SourceRole = "unowned" }, func(f *agreementFailure) { f.Tuple.Target = "unowned" }, func(f *agreementFailure) { f.Tuple.Section = "unowned" }, func(f *agreementFailure) { f.Tuple.State = "unowned" }, func(f *agreementFailure) { f.Fragment = "^unowned" }, func(f *agreementFailure) { f.Direction = "unowned" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Multiplicity = 0 }, func(f *agreementFailure) { f.Multiplicity = -1 }, func(f *agreementFailure) { f.PagePresent = !f.PagePresent }, func(f *agreementFailure) { f.JudgeAccepted = !f.JudgeAccepted }, func(f *agreementFailure) { f.ExcerptFound = !f.ExcerptFound }, func(f *agreementFailure) { f.Cut += "unowned" }} {
		other := *f
		change(&other)
		if k, _, _ := agreementNativeListAddressDifference(c, &other, a, fs, p); k != "" {
			t.Fatalf("caught: tight-list address borrowed signature %s", agreementSignature(&other))
		}
	}
	otherPage := *a
	otherPage.Blocks = append(slices.Clone(a.Blocks), "^unowned")
	if k, _, _ := agreementNativeListAddressDifference(c, f, &otherPage, fs, p); k != "" {
		t.Fatal("caught: tight-list address borrowed changed whole page set")
	}
	partial := slices.Clone(fs)
	for i := range partial {
		if partial[i].Property == "P3" && agreementSignature(&partial[i]) == agreementSignature(f) {
			partial = append(partial[:i], partial[i+1:]...)
			break
		}
	}
	for _, changed := range [][]agreementFailure{nil, partial, append(slices.Clone(fs), *f)} {
		if k, _, _ := agreementNativeListAddressDifference(c, f, a, changed, p); k != "" {
			t.Fatal("caught: tight-list address borrowed changed whole P3 pool")
		}
		if agreementNativeListAddressBudget(t, c.Body, a, changed).Address.Body != "" {
			t.Fatal("caught: tight-list address budget borrowed changed whole P3 pool")
		}
	}
	for _, change := range []func(*agreementNativeListAddressPayload){
		func(p *agreementNativeListAddressPayload) { p.Owners = nil },
		func(p *agreementNativeListAddressPayload) {
			p.Owners = maps.Clone(p.Owners)
			p.Owners["^unowned"] = []agreementNativeListAddressOwner{{Field: 0, Node: 0}}
		},
		func(p *agreementNativeListAddressPayload) {
			p.Owners = maps.Clone(p.Owners)
			for name := range p.Owners {
				delete(p.Owners, name)
				break
			}
		},
		func(p *agreementNativeListAddressPayload) {
			p.Owners = maps.Clone(p.Owners)
			for name, v := range p.Owners {
				p.Owners[name] = append(slices.Clone(v), agreementNativeListAddressOwner{Field: 0, Node: 0})
				break
			}
		},
		func(p *agreementNativeListAddressPayload) {
			p.Owners = maps.Clone(p.Owners)
			for name, v := range p.Owners {
				v = slices.Clone(v)
				v[0].Field++
				p.Owners[name] = v
				break
			}
		},
		func(p *agreementNativeListAddressPayload) {
			p.Owners = maps.Clone(p.Owners)
			for name, v := range p.Owners {
				v = slices.Clone(v)
				v[0].Node++
				p.Owners[name] = v
				break
			}
		},
	} {
		other := *p
		change(&other)
		if k, _, _ := agreementNativeListAddressDifference(c, f, a, fs, &other); k != "" {
			t.Fatal("caught: tight-list address borrowed changed complete owner roster")
		}
	}

	for _, attr := range []string{"List", "Item"} {
		other := *p
		other.Owners = maps.Clone(p.Owners)
		for name, v := range p.Owners {
			v = slices.Clone(v)
			if attr == "List" {
				v[0].List++
			} else {
				v[0].Item++
			}
			other.Owners[name] = v
			break
		}
		if k, _, _ := agreementNativeListAddressDifference(c, f, a, fs, &other); k != "" {
			t.Fatal("caught: tight-list address borrowed changed container indices")
		}
	}
	for _, change := range []func(*agreementNativeListAddressPayload){
		func(p *agreementNativeListAddressPayload) { p.Address.Source.Body += "unowned" }, func(p *agreementNativeListAddressPayload) { p.Address.Body += "unowned" }, func(p *agreementNativeListAddressPayload) { p.Address.Names = nil }, func(p *agreementNativeListAddressPayload) {
			p.Address.Blocks = append(slices.Clone(p.Address.Blocks), "^unowned")
		}, func(p *agreementNativeListAddressPayload) {
			p.Address.WitnessBlocks = append(slices.Clone(p.Address.WitnessBlocks), "^unowned")
		}, func(p *agreementNativeListAddressPayload) { p.Address.Original = nil }, func(p *agreementNativeListAddressPayload) { p.Address.Witness = nil }, func(p *agreementNativeListAddressPayload) { p.Address.Signatures = nil },
		func(p *agreementNativeListAddressPayload) {
			p.Address.Original = maps.Clone(p.Address.Original)
			p.Address.Original["^unowned"] = agreementNativeAddressReceipt{}
		}, func(p *agreementNativeListAddressPayload) {
			p.Address.Witness = maps.Clone(p.Address.Witness)
			p.Address.Witness["^unowned"] = agreementNativeAddressReceipt{}
		},
		func(p *agreementNativeListAddressPayload) {
			p.Address.Original = maps.Clone(p.Address.Original)
			for name, r := range p.Address.Original {
				r.Cut += "unowned"
				p.Address.Original[name] = r
			}
		}, func(p *agreementNativeListAddressPayload) {
			p.Address.Witness = maps.Clone(p.Address.Witness)
			for name, r := range p.Address.Witness {
				r.Cut += "unowned"
				p.Address.Witness[name] = r
			}
		},
	} {
		other := *p
		change(&other)
		if k, _, _ := agreementNativeListAddressDifference(c, f, a, fs, &other); k != "" {
			t.Fatal("caught: tight-list address borrowed changed complete public evidence")
		}
	}
	for index, ledger := range []map[string]agreementNativeAddressReceipt{p.Address.Original, p.Address.Witness} {
		for name := range ledger {
			for _, change := range []func(*agreementNativeAddressReceipt){func(r *agreementNativeAddressReceipt) { r.Page = !r.Page }, func(r *agreementNativeAddressReceipt) { r.Judge = !r.Judge }, func(r *agreementNativeAddressReceipt) { r.Found = !r.Found }} {
				other := *p
				if index == 0 {
					other.Address.Original = maps.Clone(p.Address.Original)
					r := other.Address.Original[name]
					change(&r)
					other.Address.Original[name] = r
				} else {
					other.Address.Witness = maps.Clone(p.Address.Witness)
					r := other.Address.Witness[name]
					change(&r)
					other.Address.Witness[name] = r
				}
				if k, _, _ := agreementNativeListAddressDifference(c, f, a, fs, &other); k != "" {
					t.Fatal("caught: tight-list address borrowed changed complete public roles")
				}
			}
		}
	}
}
